{
  "name": "FTP文件上传组件",
  "name_en": "FTP File Upload Component",
  "manufacturer": "",
  "description": "这是一个非物理实验辅助软件组件，用于通过 FTP 将文件上传到远程路径，并可在需要时创建多级远程目录。适合用于实验数据、结果文件或日志的网络传输与归档。",
  "description_en": "This is a non-physical laboratory helper software component used to upload files to a remote path via FTP, with support for creating nested remote directories when needed. It is suitable for transferring and archiving experiment data, result files, or logs over a network.",
  "actions": [
    {
      "action_name": "auto-uploadFile",
      "description": "将文件上传到远程 FTP 路径。",
      "description_en": "Upload a file to a remote FTP path."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 FTP 连接。",
      "description_en": "Close the FTP connection."
    }
  ],
  "tag_hints": [
    "FTP file transfer",
    "file upload",
    "remote storage",
    "experiment data archival",
    "network file transfer"
  ]
}

